<?php defined('BASEPATH') or exit('No direct script access allowed');$company_page_title='Rascunhos privados de faturas';require APPPATH.'views/admin/companies/layout_head.php';$esc=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');$url=fn($q='')=>CompanyRequestScope::adminUrl($this,'company_invoice_drafts'.$q);$labels=['open'=>'Rascunho privado','cancelled'=>'Rascunho cancelado','issued'=>'Fatura emitida'];
