<?= form_open($url(),['id'=>'invoice-draft-copy']);$hidden('copy_invoice',$request_key); ?><input type="hidden" name="source_invoice_id" value="<?= (int)$copy['id']; ?>"><input type="hidden" name="review[source_revision]" value="<?= $esc($copy['revision']); ?>"><label for="draft-copy-date">Data proposta de emissão</label><input class="form-control" id="draft-copy-date" type="date" name="review[date]" required><label for="draft-copy-due">Novo vencimento</label><input class="form-control" id="draft-copy-due" type="date" name="review[due_date]" required><label for="draft-copy-note">Observação</label><textarea class="form-control" id="draft-copy-note" name="review[note]" maxlength="20000"><?= $esc($copy['note']); ?></textarea><label><input type="checkbox" name="review[confirm_amounts]" value="1" required> Conferi os itens e os valores da origem e quero preparar um rascunho privado.</label><button type="submit">Criar rascunho privado da cópia revisada</button><?= form_close(); ?>
<?php } ?>
<?php if($draft){ ?><h2 id="invoice-draft-state"><?= $esc($labels[$draft['state']]); ?> #<?= (int)$draft['id']; ?></h2><p><?= $esc($draft['context']['identity']['legal_name'].' → '.$draft['context']['recipient']['name']); ?> · Revisão <?= (int)$draft['revision']; ?> · <?= $esc($draft['context']['currency']['name']); ?></p><?php if($draft['source']){ ?><p id="draft-source">Cópia revisada de <?= $esc($draft['source']['invoice']['number']); ?>; origem <?= $draft['source']['invoice']['status']===5?'cancelada':'preservada'; ?>. Os vínculos financeiros da origem não são transferidos.</p><?php } ?>
<?php if($draft['invoice_id']!==null){ ?><p><a id="draft-issued-invoice" href="<?= $esc(CompanyRequestScope::adminUrl($this,'company_invoices?invoice='.$draft['invoice_id'])); ?>">Abrir fatura emitida <?= $esc($draft['issue']['number']); ?></a></p><?php } ?>
<?php $amounts=CompanyInvoiceCopiesInput::canonical($draft['payload']); ?><p id="draft-total">Subtotal <?= $esc($amounts['subtotal']); ?> · Tributos <?= $esc($amounts['tax']); ?> · Desconto <?= $esc($amounts['discount_total']); ?> · Ajuste <?= $esc($amounts['adjustment']); ?> · <strong>Total <?= $esc($amounts['total']); ?></strong></p>
<?php if($draft['state']!=='open'||!$can_edit){ ?><ul><?php foreach($draft['payload']['items']as$line){ ?><li><?= $esc($line['description'].' · '.$line['qty'].' × '.$line['rate']); ?><pre><?= $esc($line['long_description']??''); ?></pre></li><?php } ?></ul><?php } ?>
<?php } ?>
<?php $editing=$draft!==null&&$draft['state']==='open';if(!$copy&&(($draft===null&&$can_create)||($editing&&$can_edit))){$payload=$draft['payload']??['client_id'=>null,'currency'=>null,'date'=>gmdate('Y-m-d'),'due_date'=>gmdate('Y-m-d',time()+30*86400),'items'=>[['description'=>'','qty'=>'1.00','rate'=>'','taxes'=>[]]],'note'=>'']; ?>
<h2><?= $editing?'Editar rascunho privado':'Novo rascunho privado'; ?></h2><p>Salvar registra a revisão e a identidade atual da empresa. A emissão é uma ação posterior explícita.</p><?= form_open($url(),['id'=>'invoice-draft-editor']);$hidden($editing?'change':'create',$request_key);if($editing){ ?><input type="hidden" name="draft_id" value="<?= (int)$draft['id']; ?>"><input type="hidden" name="revision" value="<?= (int)$draft['revision']; ?>"><?php } ?>
