<label for="draft-date">Data proposta de emissão</label><input class="form-control" id="draft-date" type="date" name="payload[date]" value="<?= $esc($payload['date']); ?>" required><label for="draft-due">Vencimento</label><input class="form-control" id="draft-due" type="date" name="payload[due_date]" value="<?= $esc($payload['due_date']); ?>" required>
