<?php $fieldPrefix='draft-';$adjustments=$payload;ob_start();require APPPATH.'views/admin/companies/invoice_adjustment_fields.php';echo str_replace('name="invoice[','name="payload[',ob_get_clean()); ?>
<label for="draft-note">Observação</label><textarea class="form-control" id="draft-note" name="payload[note]" maxlength="20000"><?= $esc($payload['note']); ?></textarea><button id="draft-save" type="submit">Salvar rascunho privado</button><?= form_close(); ?><?php } ?>
<?php if($editing&&$can_create){ ?><?= form_open($url(),['id'=>'invoice-draft-issue']);$hidden('issue',hash('sha256',$request_key.'issue')); ?><input type="hidden" name="draft_id" value="<?= (int)$draft['id']; ?>"><input type="hidden" name="revision" value="<?= (int)$draft['revision']; ?>"><label><input id="draft-confirm-issue" type="checkbox" name="confirm_issue" value="1" required> Revisei este rascunho e autorizo emitir uma fatura numerada em aberto.</label><p>A emissão usa os valores salvos e exige que a identidade e as configurações atuais correspondam à revisão. Ela não envia mensagem nem opera o banco.</p><button id="draft-issue" type="submit">Emitir fatura numerada revisada</button><?= form_close(); ?><?php } ?>
